/**
 * Domain tables live in ticket-schema.ts; auth tables in auth-schema.ts, which
 * is generated by `@better-auth/cli generate` and must never be edited by hand.
 *
 * Re-exported rather than imported piecemeal so drizzle.config.ts can keep
 * pointing at this one file and `drizzle({ client, schema })` sees everything.
 */
export * from "./auth-schema.ts";
export * from "./ticket-schema.ts";
